frappe.ui.form.on('Site', {
	refresh(frm) {
		frm.add_custom_button('Extend Trial', () => {
		    frappe.set_route('List', 'Site Trial Extension', {'site': frm.doc.name})
		}, 'Subscription')

		frm.add_custom_button('Change Plan', () => {
		  //  frappe.new_doc('Site Plan Change', { site: frm.doc.name });
		  let d = new frappe.ui.Dialog({
		      title: 'Change Plan',
		      fields: [
		          {fieldtype: 'Link', fieldname: 'plan', label: 'Plan', options: 'Site Plan', reqd: 1},
		          {fieldtype: 'Small Text', fieldname: 'reason', label: 'Reason', reqd: 1},
		      ],
		      primary_action({ plan, reason }) {
		          frappe.call('site-change-plan', { site: frm.doc.name, plan, reason })
		            .then(r => {
		                if (!r.exc) {
		                    frappe.show_alert(`Plan changed to ${plan}`);
		                }
		            });
		      }
		  });
		  d.show()
		}, 'Subscription')

	    frm.add_custom_button('Change Team', () => {
		    frappe.new_doc('Team Change', { document_name: frm.doc.name, document_type: 'Site', from_team: frm.doc.team, transfer_completed: 1 });
		}, 'Subscription')

		frm.add_custom_button('Change Server', () => {
		    frappe.set_route('List', 'Site Migration', {'site': frm.doc.name})
		}, 'Actions')



		console_access_help(frm);
		site_information_for_support_staff(frm);
	}
})

async function site_information_for_support_staff(frm) {
    let content = ''
    let result = await frappe.db.get_value('Server', frm.doc.server, 'team')
    if (result.message.team == frm.doc.team) {
        content += `<div class="mt-2 container-fluid">
            <div class="row"><div class="col">Dedicated Server Plan</div></div>
        </div>
        `
    }
    frm.dashboard.set_headline(content);
}

async function console_access_help(frm) {
	let steps = `- Create [User SSH Certificate](https://frappecloud.com/app/user-ssh-certificate/new-user-ssh-certificate?access_server=${frm.doc.server})
- ssh into ${frm.doc.server} (using instructions in User SSH Certificate)
- \`docker exec -it ${frm.doc.bench} bash\`
- \`bench --site ${frm.doc.name} console\`

Alternatively, if you have direct SSH use this single command:

\`ssh frappe@frappe.cloud -t 'ssh root@${frm.doc.server} -t docker exec -it ${frm.doc.bench} bash'\`
`


	frm.add_custom_button('Console Access Help', () => {
	    frappe.msgprint(frappe.markdown('### Steps to gain console access\n\n\n' + steps + '\n'));
	});
}

frappe.ui.form.on('Job Card', {
    refresh(frm) {

        // 1) Filter main field: Job Card.employee
        frm.set_query('employee', () => {
            return {
                filters: {
                    name: ["like", "HR-WRKR-%"],
                    status: "Active"
                }
            };
        });

        // 2) Filter employee inside the child table time_logs
        if (frm.fields_dict?.time_logs) {
            frm.fields_dict.time_logs.grid.get_field('employee').get_query = function() {
                return {
                    filters: {
                        name: ["like", "HR-WRKR-%"],
                        status: "Active"
                    }
                };
            };
        }

        // 3) Filter employee inside the popup (Table MultiSelect)
        // This applies to: "Select Employees" prompt → Job Card Time Log.employee
        setTimeout(() => {
            try {
                let df = frappe.meta.get_docfield(
                    'Job Card Time Log',
                    'employee',
                    frm.doc.doctype
                );

                if (df) {
                    df.get_query = () => {
                        return {
                            filters: {
                                name: ["like", "HR-WRKR-%"],
                                status: "Active"
                            }
                        };
                    };
                }
            } catch (e) {
                console.warn("Popup employee filter could not be applied yet", e);
            }
        }, 300);
    }
});

frappe.ui.form.on("Shipment", {

    refresh(frm) {

    frm.add_custom_button(__('Import From'), function () {

        let options = "";

        const shipment_way = (frm.doc.custom_shipment_way || "").trim();

        if (shipment_way === "Outgoing") {
            options = "Delivery Note";
        }
        else if (shipment_way === "Incoming") {
            options = "Purchase Order";
        }
        else {
            frappe.msgprint(__('Please select Shipment Way'));
            return;
        }

        const dialog = new frappe.ui.Dialog({
            title: __('Select Source'),

            fields: [
                {
                    fieldname: 'source',
                    fieldtype: 'Select',
                    label: 'Fetch From',
                    options: options,
                    reqd: 1,
                    default: options
                }
            ],

            primary_action_label: __('Next'),

            primary_action(values) {

                dialog.hide();

                if (values.source === "Delivery Note") {
                    fetch_from_delivery_note(frm);
                }

                if (values.source === "Purchase Order") {
                    fetch_from_purchase_order(frm);
                }

            }
        });

        dialog.show();

    });

},

    validate(frm) {

        (frm.doc.custom_shipment_box || []).forEach(row => {

            if (row.net_weight > row.gross_weight) {

                frappe.throw(
                    `Row ${row.idx}: Net Weight cannot be greater than Gross Weight`
                );

            }

        });

    }

});


