frappe.ui.form.on("Shipment Box", {

    custom_shipment_box_add(frm) {
        update_inner_box_numbers(frm);
    },

    custom_shipment_box_remove(frm) {
        update_inner_box_numbers(frm);
    },

    box_template(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        if (!row.box_template) return;

        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight"
        ).then(r => {

            const template_weight = flt(r.message.weight);
            const net = flt(row.net_weight);

            frappe.model.set_value(
                cdt,
                cdn,
                "gross_weight",
                net + template_weight
            );

        });

    },

    net_weight(frm, cdt, cdn) {

        const row = locals[cdt][cdn];

        if (!row.box_template) {
            frappe.model.set_value(cdt, cdn, "gross_weight", row.net_weight);
            return;
        }

        frappe.db.get_value(
            "Shipment Parcel Template",
            row.box_template,
            "weight"
        ).then(r => {

            const template_weight = flt(r.message.weight);

            frappe.model.set_value(
                cdt,
                cdn,
                "gross_weight",
                flt(row.net_weight) + template_weight
            );

        });

    }

});


