function open_items_dialog(frm, items, source, reference) {

    const dialog = new frappe.ui.Dialog({

        title: __('Select Items'),
        size: 'extra-large',

        fields: [
            {
                fieldname: 'items',
                fieldtype: 'Table',
                cannot_add_rows: true,

                data: items.map(d => ({
                    select: 1,
                    item_code: d.item_code,
                    item_name: d.item_name,
                    // description: strip_html(d.description),
                    description: (d.description || "").replace(/<br\s*\/?>/gi, "\n"),
                    qty: d.qty,
                    uom: d.uom,
                    schedule_date: d.schedule_date

                })),

                fields: [
                    { fieldtype: 'Check', fieldname: 'select', label: 'Select', in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'item_code', label: 'Item Code', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'item_name', label: 'Item Name', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Float', fieldname: 'qty', label: 'Qty', in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'uom', label: 'UOM', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Date', fieldname: 'schedule_date', label: 'Required By', read_only: 1, in_list_view: 1 }
                ]
            }
        ],

        primary_action_label: __('Add to Shipment'),

        primary_action(values) {

            const selected = (values.items || []).filter(
                row => row.select && row.qty > 0
            );

            if (!selected.length) {
                frappe.msgprint(__('Please select at least one item'));
                return;
            }

            selected.forEach(row => {

                let child = frm.add_child("custom_shipment_box");

                let count = frm.doc.custom_shipment_box.length;

                child.inner_box_no = "P-" + count;

                if (source === "Delivery Note") {
                    child.delivery_note = reference;
                }

                if (source === "Purchase Order") {
                    child.purchase_order = reference;
                }

                child.item_code = row.item_code;
                child.item_name = row.item_name;
                child.item_description = strip_html(row.description);
                child.qty = row.qty;
                child.uom = row.uom;
                child.custom_po_required_by = row.schedule_date;

                child.packed = 0;
                child.net_weight = 0;
                child.gross_weight = 0;

            });

            frm.refresh_field("custom_shipment_box");

            dialog.hide();

        }

    });

    dialog.show();

}


// ==========================================================
// REMOVE HTML
// ==========================================================

function strip_html(html) {

    if (!html) return "";

    let tmp = document.createElement("DIV");
    tmp.innerHTML = html;

    return tmp.textContent || tmp.innerText || "";

}

frappe.ui.form.on("Shipment Outer Box", {
    select_inner_boxes(frm, cdt, cdn) {
        const ob = locals[cdt][cdn];

        const boxes = (frm.doc.custom_shipment_box || []).map(b => ({
            label: `${b.inner_box_no} (GW: ${b.gross_weight}, NW: ${b.net_weight})`,
            value: b.inner_box_no
        }));

        if (!boxes.length) {
            frappe.msgprint("No Inner Boxes available");
            return;
        }

        const dialog = new frappe.ui.Dialog({
            title: __("Select Inner Boxes"),
            fields: [{
                fieldtype: "MultiCheck",
                fieldname: "inner_boxes",
                label: "Inner Boxes",
                options: boxes
            }],
            primary_action_label: __("Update Outer Box"),
            primary_action(values) {
                const selected = values.inner_boxes || [];

                if (!selected.length) {
                    frappe.msgprint("Select at least one Inner Box");
                    return;
                }

                let gross = 0;
                let net = 0;

                // Reset previous mapping for this outer box
                (frm.doc.custom_shipment_box || []).forEach(b => {
                    if (b.outer_box === ob.outer_box_no) {
                        b.outer_box = "";
                    }
                });

                // Map selected inner boxes
                (frm.doc.custom_shipment_box || []).forEach(b => {
                    if (selected.includes(b.inner_box_no)) {
                        b.outer_box = ob.outer_box_no;
                        gross += flt(b.gross_weight);
                        net += flt(b.net_weight);
                    }
                });

                // ✅ UPDATE Shipment Outer Box
                frappe.model.set_value(cdt, cdn, "inner_box", selected.join(", "));
                frappe.model.set_value(cdt, cdn, "gross_weight", gross);
                frappe.model.set_value(cdt, cdn, "net_weight", net);

                frm.refresh_field("custom_shipment_box");
                frm.refresh_field("custom_outer_box");

                dialog.hide();
            }
        });

        dialog.show();
    }
});

frappe.ui.form.on("Shipment", {

    refresh(frm) {

        // Run only for New Document
        if (!frm.is_new()) {
            return;
        }

        // Prevent Multiple Runs
        if (frm.__shipment_loaded) {
            return;
        }

        frm.__shipment_loaded = true;

        // ============================================
        // SET SHIPMENT WAY
        // ============================================

        frm.set_value(
            "custom_shipment_way",
            "Outgoing"
        );

        // ============================================
        // CHECK DELIVERY NOTE TABLE
        // ============================================

        if (!frm.doc.shipment_delivery_note ||
            !frm.doc.shipment_delivery_note.length) {

            return;
        }

        // ============================================
        // CLEAR TABLES
        // ============================================

        frm.clear_table("custom_shipment_box");
        frm.clear_table("custom_outer_box");

        let inner_box_index = 1;
        let processed_delivery_notes = [];

        // ============================================
        // LOOP DELIVERY NOTES
        // ============================================

        frm.doc.shipment_delivery_note.forEach(dn_row => {

            if (!dn_row.delivery_note) {
                return;
            }

            // Avoid Duplicate DN
            if (
                processed_delivery_notes.includes(
                    dn_row.delivery_note
                )
            ) {
                return;
            }

            processed_delivery_notes.push(
                dn_row.delivery_note
            );

            // ========================================
            // GET DELIVERY NOTE
            // ========================================

            frappe.call({

                method: "frappe.client.get",

                args: {
                    doctype: "Delivery Note",
                    name: dn_row.delivery_note
                },

                callback: function(r) {

                    if (!r.message) {
                        return;
                    }

                    let dn = r.message;

                    (dn.items || []).forEach(item => {

                        let qty = flt(item.qty);

                        if (qty <= 0) {
                            return;
                        }

                        // ============================
                        // ADD ROW
                        // ============================

                        let row = frm.add_child(
                            "custom_shipment_box"
                        );

                        row.inner_box_no =
                            `D-${inner_box_index}`;

                        row.delivery_note = dn.name;

                        row.item_code = item.item_code;

                        row.item_name = item.item_name;

                        row.item_description =
                            item.description ||
                            item.item_name;

