frappe.ui.form.on("Shipment", {

    refresh(frm) {

        // Run only for New Document
        if (!frm.is_new()) {
            return;
        }

        // Prevent Multiple Runs
        if (frm.__shipment_loaded) {
            return;
        }

        frm.__shipment_loaded = true;

        // ============================================
        // SET SHIPMENT WAY
        // ============================================

        frm.set_value(
            "custom_shipment_way",
            "Outgoing"
        );

        // ============================================
        // CHECK DELIVERY NOTE TABLE
        // ============================================

        if (!frm.doc.shipment_delivery_note ||
            !frm.doc.shipment_delivery_note.length) {

            return;
        }

        // ============================================
        // CLEAR TABLES
        // ============================================

        frm.clear_table("custom_shipment_box");
        frm.clear_table("custom_outer_box");

        let inner_box_index = 1;
        let processed_delivery_notes = [];

        // ============================================
        // LOOP DELIVERY NOTES
        // ============================================

        frm.doc.shipment_delivery_note.forEach(dn_row => {

            if (!dn_row.delivery_note) {
                return;
            }

            // Avoid Duplicate DN
            if (
                processed_delivery_notes.includes(
                    dn_row.delivery_note
                )
            ) {
                return;
            }

            processed_delivery_notes.push(
                dn_row.delivery_note
            );

            // ========================================
            // GET DELIVERY NOTE
            // ========================================

            frappe.call({

                method: "frappe.client.get",

                args: {
                    doctype: "Delivery Note",
                    name: dn_row.delivery_note
                },

                callback: function(r) {

                    if (!r.message) {
                        return;
                    }

                    let dn = r.message;

                    (dn.items || []).forEach(item => {

                        let qty = flt(item.qty);

                        if (qty <= 0) {
                            return;
                        }

                        // ============================
                        // ADD ROW
                        // ============================

                        let row = frm.add_child(
                            "custom_shipment_box"
                        );

                        row.inner_box_no =
                            `D-${inner_box_index}`;

                        row.delivery_note = dn.name;

                        row.item_code = item.item_code;

                        row.item_name = item.item_name;

                        row.item_description =
                            item.description ||
                            item.item_name;

                        row.qty = qty;

                        row.uom = item.uom;

                        row.gross_weight = 0;

                        row.net_weight = 0;

                        row.packed = 0;

                        row.outer_box = "";

                        inner_box_index++;
                    });

                    frm.refresh_field(
                        "custom_shipment_box"
                    );
                }
            });

        });

    }

});

frappe.ui.form.on("Shipment", {

    refresh(frm) {

    frm.add_custom_button(__('Import From'), function () {

        const shipment_way = (frm.doc.custom_shipment_way || "").trim();

        let options = "";

        if (shipment_way === "Outgoing") {
            options = "Delivery Note";
        }
        else if (shipment_way === "Incoming") {
            options = "Purchase Order";
        }
        else {
            frappe.msgprint(__('Please select Shipment Way'));
            return;
        }

        const dialog = new frappe.ui.Dialog({
            title: __('Select Source'),

            fields: [
                {
                    fieldname: 'source',
                    fieldtype: 'Select',
                    label: 'Fetch From',
                    reqd: 1
                }
            ],

            primary_action_label: __('Next'),

            primary_action(values) {

                dialog.hide();

                if (values.source === "Delivery Note") {
                    fetch_from_delivery_note(frm);
                }

                if (values.source === "Purchase Order") {
                    fetch_from_purchase_order(frm);
                }

            }
        });

        // SET OPTIONS HERE
        dialog.set_df_property('source', 'options', options);

        // SET DEFAULT VALUE
        dialog.set_value('source', options);

        dialog.show();

    });

},

    validate(frm) {

        (frm.doc.custom_shipment_box || []).forEach(row => {

            if (row.net_weight > row.gross_weight) {

                frappe.throw(
                    `Row ${row.idx}: Net Weight cannot be greater than Gross Weight`
                );

            }

        });

    }

});


