// ==========================================================
// ITEM SELECTION DIALOG
// ==========================================================

function open_items_dialog(frm, items, source, reference) {

    const dialog = new frappe.ui.Dialog({

        title: __('Select Items'),
        size: 'extra-large',

        fields: [
            {
                fieldname: 'items',
                fieldtype: 'Table',
                cannot_add_rows: true,

                data: items.map(d => ({
                    select: 1,
                    item_code: d.item_code,
                    item_name: d.item_name,
                    // description: strip_html(d.description),
                    description: (d.description || "").replace(/<br\s*\/?>/gi, "\n"),
                    qty: d.qty,
                    uom: d.uom,
                    schedule_date: d.schedule_date

                })),

                fields: [
                    { fieldtype: 'Check', fieldname: 'select', label: 'Select', in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'item_code', label: 'Item Code', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'item_name', label: 'Item Name', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Float', fieldname: 'qty', label: 'Qty', in_list_view: 1 },
                    { fieldtype: 'Data', fieldname: 'uom', label: 'UOM', read_only: 1, in_list_view: 1 },
                    { fieldtype: 'Date', fieldname: 'schedule_date', label: 'Required By', read_only: 1, in_list_view: 1 }
                ]
            }
        ],

        primary_action_label: __('Add to Shipment'),

        primary_action(values) {

            const selected = (values.items || []).filter(
                row => row.select && row.qty > 0
            );

            if (!selected.length) {
                frappe.msgprint(__('Please select at least one item'));
                return;
            }

            selected.forEach(row => {

                let child = frm.add_child("custom_shipment_box");

                let count = frm.doc.custom_shipment_box.length;

                child.inner_box_no = "P-" + count;

                if (source === "Delivery Note") {
                    child.delivery_note = reference;
                }

                if (source === "Purchase Order") {
                    child.purchase_order = reference;
                }

                child.item_code = row.item_code;
                child.item_name = row.item_name;
                child.item_description = strip_html(row.description);
                child.qty = row.qty;
                child.uom = row.uom;
                child.custom_po_required_by = row.schedule_date;

                child.packed = 0;
                child.net_weight = 0;
                child.gross_weight = 0;

            });

            frm.refresh_field("custom_shipment_box");

            dialog.hide();

        }

    });

    dialog.show();

}


// ==========================================================
// REMOVE HTML
// ==========================================================

function strip_html(html) {

    if (!html) return "";

    let tmp = document.createElement("DIV");
    tmp.innerHTML = html;

    return tmp.textContent || tmp.innerText || "";

}
